import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        FastReader in = new FastReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskB solver = new TaskB();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskB {
        enum State {
            OUTSIDE_NO_WORD,
            OUTSIDE_WORD,
            INSIDE_NO_WORD,
            INSIDE_WORD
        }

        public void solve(int testNumber, FastReader in, PrintWriter out) {
            int n = in.nextInt();
            String s = (in.nextLine() + "_").substring(0, n + 1);
            State state = State.OUTSIDE_NO_WORD;
            int wordsInside = 0;
            int wordLen = 0;
            int maxOutside = 0;

            for (int i = 0; i < s.length(); i++) {
                char c = s.charAt(i);
                boolean delimiter = c == '_' || c == '(' || c == ')';

                switch (state) {
                    case OUTSIDE_NO_WORD:
                        if (delimiter) {
                            if (c == '(') state = State.INSIDE_NO_WORD;
                            else if (c == ')') state = State.OUTSIDE_NO_WORD;
                        } else {
                            state = State.OUTSIDE_WORD;
                            wordLen = 1;
                        }
                        break;

                    case OUTSIDE_WORD:
                        if (delimiter) {
                            if (wordLen > maxOutside) maxOutside = wordLen;
                            wordLen = 0;
                            if (c == '(') state = State.INSIDE_NO_WORD;
                            else if (c == ')') state = State.OUTSIDE_NO_WORD;
                            else state = State.OUTSIDE_NO_WORD;
                        } else {
                            wordLen++;
                        }
                        break;

                    case INSIDE_NO_WORD:
                        if (delimiter) {
                            if (c == '(') state = State.INSIDE_NO_WORD;
                            else if (c == ')') state = State.OUTSIDE_NO_WORD;
                        } else {
                            state = State.INSIDE_WORD;
                            wordLen = 1;
                        }
                        break;

                    case INSIDE_WORD:
                        if (delimiter) {
                            wordsInside++;
                            wordLen = 0;
                            if (c == '(') state = State.INSIDE_NO_WORD;
                            else if (c == ')') state = State.OUTSIDE_NO_WORD;
                            else state = State.INSIDE_NO_WORD;
                        } else {
                            wordLen++;
                        }
                        break;
                }
            }

            out.printf("%d %d", maxOutside, wordsInside);
        }
    }

    static class FastReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        String nextLine() {
            String str = "";
            try {
                str = reader.readLine();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
            return str;
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}
